import React, { useContext } from "react";
import { Route, Routes } from "react-router-dom";

import Apps from "./Apps";
import Funds from "./Funds";
import Holdings from "./Holdings";
import Orders from "./Orders";
import Positions from "./Positions";
import Summary from "./Summary";
import WatchList from "./WatchList";
import BuyActionWindow from "./BuyActionWindow";

import GeneralContext, { GeneralContextProvider } from "./GeneralContext";

// Sub-component that actually sits inside the Provider context tree
const DashboardContent = () => {
  // Grab the visibility states exposed by GeneralContext
  const { isBuyWindowOpen, selectedStockUID } = useContext(GeneralContext);

  return (
    <div
      className="dashboard-container"
      style={{ display: "flex", position: "relative" }}
    >
      <WatchList />
      <div className="content" style={{ flex: 1 }}>
        <Routes>
          <Route exact path="/" element={<Summary />} />
          <Route path="/orders" element={<Orders />} />
          <Route path="/holdings" element={<Holdings />} />
          <Route path="/positions" element={<Positions />} />
          <Route path="/funds" element={<Funds />} />
          <Route path="/apps" element={<Apps />} />
        </Routes>
      </div>

      {/* Conditionally render the modal right here over your grid workspace */}
      {isBuyWindowOpen && <BuyActionWindow uid={selectedStockUID} />}
    </div>
  );
};

const Dashboard = () => {
  return (
    <GeneralContextProvider>
      <DashboardContent />
    </GeneralContextProvider>
  );
};

export default Dashboard;
